// ── Config (non-secret; secrets live in n8n credentials) ─────────────────────
const CONFIG = {
  jiraBaseUrl: 'https://YOUR-SITE.atlassian.net',
  // Jira custom field holding release notes, e.g. 'customfield_10050'. Empty → use description.
  releaseNotesField: '',
  // Google Chat space webhook, WITHOUT ?key=&token= (those come from the credential).
  googleChatUrl: 'https://chat.googleapis.com/v1/spaces/YOUR_SPACE_ID/messages',
  mentionAllOnFailure: true,
  maxTickets: 15,
};

// ── Validate + normalize the GitHub Actions payload ──────────────────────────
const body = $input.first().json.body ?? {};
const str = (v) => (typeof v === 'string' ? v : '');
const status = str(body.status);
if (!['success', 'failure', 'cancelled'].includes(status)) {
  throw new Error('Invalid deploy payload: status must be success | failure | cancelled');
}
const KEY = /^[A-Z][A-Z0-9]{1,9}-\d+$/;
const ids = (Array.isArray(body.jira_ticket_ids) ? body.jira_ticket_ids : [body.jira_ticket_id])
  .filter((k) => typeof k === 'string' && KEY.test(k));
const jiraTicketIds = [...new Set(ids)].slice(0, CONFIG.maxTickets);

const commits = (Array.isArray(body.commits) ? body.commits : [])
  .filter((c) => c && typeof c === 'object')
  .map((c) => ({ sha: str(c.sha), title: str(c.title), author: str(c.author) }));

return [{
  json: {
    config: CONFIG,
    status,
    environment: str(body.environment) || 'production',
    repository: str(body.repository),
    ref: str(body.ref),
    commitSha: str(body.commit_sha),
    commitMessage: str(body.commit_message),
    commitUrl: str(body.commit_url),
    compareUrl: str(body.compare_url),
    author: str(body.author),
    triggeredBy: str(body.triggered_by),
    jiraTicketIds,
    commits,
    runUrl: str(body.run_url),
    jobUrl: str(body.job_url) || str(body.run_url),
    runAttempt: Number(body.run_attempt) || 1,
    failedStep: str(body.failed_step),
  },
}];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s);
const shortSha = (s) => String(s || '').slice(0, 7);
const link = (url, text) => (url ? '<a href="' + esc(url) + '">' + esc(text) + '</a>' : esc(text));
const button = (text, url) => ({ text, onClick: { openLink: { url } } });
const repoUrl = (d) => (d.runUrl ? d.runUrl.split('/actions/')[0] : '');

// Jira's description / rich-text custom fields are Atlassian Document Format: flatten to text.
const adfToText = (node) => {
  if (node == null) return '';
  if (typeof node === 'string') return node;
  if (Array.isArray(node)) return node.map(adfToText).join('');
  if (node.type === 'text') return node.text || '';
  if (node.type === 'hardBreak') return '\n';
  const inner = adfToText(node.content || []);
  const block = ['paragraph', 'heading', 'listItem', 'codeBlock', 'blockquote', 'rule'];
  return block.includes(node.type) ? (node.type === 'listItem' ? '• ' : '') + inner.trim() + '\n' : inner;
};

const d = $('Normalize payload').first().json;
const { jiraBaseUrl, releaseNotesField } = d.config;
const sha = shortSha(d.commitSha);

// Items are Jira issues on the "has tickets" path, or the payload itself otherwise.
// Tickets Jira could not return (deleted, no access) arrive as error items and are skipped.
const issues = $input.all().map((i) => i.json).filter((j) => j && j.key && j.fields);
const missing = d.jiraTicketIds.filter((k) => !issues.some((i) => i.key === k));

const ticketWidgets = issues.flatMap((issue) => {
  const f = issue.fields;
  const url = jiraBaseUrl + '/browse/' + issue.key;
  const fixVersions = (f.fixVersions || []).map((v) => v.name).join(', ') || '—';
  const notes = trunc(adfToText(releaseNotesField ? f[releaseNotesField] : f.description).trim(), 300);
  const widgets = [{
    decoratedText: {
      topLabel: issue.key + ' · ' + (f.status?.name || 'Unknown') + ' · ' + (f.issuetype?.name || 'Issue'),
      text: link(url, f.summary || issue.key),
      bottomLabel: 'Assignee: ' + (f.assignee?.displayName || 'Unassigned') + ' · Fix version: ' + fixVersions,
      wrapText: true,
      startIcon: { knownIcon: 'TICKET' },
      button: button('Open', url),
    },
  }];
  if (notes) widgets.push({ textParagraph: { text: '<i>' + esc(notes).replace(/\n/g, '<br>') + '</i>' } });
  return widgets;
});
if (missing.length) {
  ticketWidgets.push({ textParagraph: { text: '<font color="#9e9e9e">Not found in Jira: ' + esc(missing.join(', ')) + '</font>' } });
}

// No ticket at all (chore / hotfix): the commit titles are the release notes.
const commitLines = d.commits.slice(0, 15).map((c) =>
  link(repoUrl(d) + '/commit/' + c.sha, shortSha(c.sha)) + ' ' + esc(trunc(c.title, 120)) + (c.author ? ' <font color="#9e9e9e">— ' + esc(c.author) + '</font>' : ''));
if (d.commits.length > 15) commitLines.push('… and ' + (d.commits.length - 15) + ' more');

const sections = [{
  header: 'Deployment',
  widgets: [
    { decoratedText: { topLabel: 'Environment', text: esc(d.environment) + ' · ' + esc(d.ref), startIcon: { knownIcon: 'STORE' } } },
    { decoratedText: { topLabel: 'Commit', text: link(d.commitUrl, sha) + ' ' + esc(trunc(d.commitMessage.split('\n')[0], 120)), wrapText: true, startIcon: { knownIcon: 'BOOKMARK' } } },
    { decoratedText: { topLabel: 'Triggered by', text: esc(d.triggeredBy || d.author), startIcon: { knownIcon: 'PERSON' } } },
  ],
}];
if (ticketWidgets.length) {
  sections.push({ header: 'Release notes · ' + issues.length + ' ticket' + (issues.length === 1 ? '' : 's'), collapsible: ticketWidgets.length > 6, uncollapsibleWidgetsCount: 6, widgets: ticketWidgets });
}
if (commitLines.length) {
  sections.push({ header: issues.length ? 'Commits' : 'Release notes (commits)', collapsible: issues.length > 0, uncollapsibleWidgetsCount: issues.length ? 0 : 1, widgets: [{ textParagraph: { text: commitLines.join('<br>') } }] });
}
const buttons = [button('View GitHub run', d.runUrl)];
if (issues.length === 1) buttons.unshift(button('Open Jira ticket', jiraBaseUrl + '/browse/' + issues[0].key));
if (d.compareUrl) buttons.push(button('Compare changes', d.compareUrl));
sections.push({ widgets: [{ buttonList: { buttons } }] });

return [{
  json: {
    chat: {
      text: '🟢 Deployed ' + d.repository + ' to ' + d.environment + ' (' + sha + ')',
      cardsV2: [{
        cardId: 'deploy-' + sha,
        card: {
          header: { title: '🟢 Deployed to ' + d.environment, subtitle: d.repository + ' · ' + sha },
          sections,
        },
      }],
    },
  },
}];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const trunc = (s, n) => (s.length > n ? s.slice(0, n - 1).trimEnd() + '…' : s);
const shortSha = (s) => String(s || '').slice(0, 7);
const link = (url, text) => (url ? '<a href="' + esc(url) + '">' + esc(text) + '</a>' : esc(text));
const button = (text, url) => ({ text, onClick: { openLink: { url } } });
const repoUrl = (d) => (d.runUrl ? d.runUrl.split('/actions/')[0] : '');

const d = $('Normalize payload').first().json;
const sha = shortSha(d.commitSha);
const cancelled = d.status === 'cancelled';
const icon = cancelled ? '⚪' : '🔴';
const verb = cancelled ? 'cancelled' : 'FAILED';
const jira = d.jiraTicketIds.map((k) => link(d.config.jiraBaseUrl + '/browse/' + k, k)).join(', ');

const widgets = [
  { decoratedText: { topLabel: 'Failed step', text: '<b>' + esc(d.failedStep || (cancelled ? 'Run was cancelled' : 'Unknown — see the run log')) + '</b>', wrapText: true, startIcon: { knownIcon: 'DESCRIPTION' } } },
  { decoratedText: { topLabel: 'Commit', text: link(d.commitUrl, sha) + ' ' + esc(trunc(d.commitMessage.split('\n')[0], 120)), wrapText: true, startIcon: { knownIcon: 'BOOKMARK' } } },
  { decoratedText: { topLabel: 'Triggered by', text: esc(d.triggeredBy || d.author) + (d.runAttempt > 1 ? ' · attempt ' + d.runAttempt : ''), startIcon: { knownIcon: 'PERSON' } } },
];
if (jira) widgets.push({ decoratedText: { topLabel: 'Tickets in this release', text: jira, wrapText: true, startIcon: { knownIcon: 'TICKET' } } });
widgets.push({ buttonList: { buttons: [button('View failed job', d.jobUrl), button('View GitHub run', d.runUrl)] } });

const alert = !cancelled && d.config.mentionAllOnFailure ? '<users/all> ' : '';
return [{
  json: {
    chat: {
      text: alert + icon + ' Production deploy ' + verb + ' for ' + d.repository + ' (' + sha + ')' + (d.failedStep ? ' at step "' + d.failedStep + '"' : '') + '. The live site was not updated by this run.',
      cardsV2: [{
        cardId: 'deploy-' + sha,
        card: {
          header: { title: icon + ' Deploy ' + verb + ' · ' + d.environment, subtitle: d.repository + ' · ' + d.ref + ' · ' + sha },
          sections: [{ widgets }],
        },
      }],
    },
  },
}];
